class Dinic {
    private $graph;
    private $level;
    private $iter;
    private $n;

    public function __construct($n) {
        $this->n = $n;
        $this->graph = array_fill(0, $n, []);
        $this->level = array_fill(0, $n, 0);
        $this->iter = array_fill(0, $n, 0);
    }

    public function addEdge($from, $to, $capacity) {
        $forward = new Edge($to, count($this->graph[$to]), $capacity);
        $backward = new Edge($from, count($this->graph[$from]), 0);
        $this->graph[$from][] = $forward;
        $this->graph[$to][] = $backward;
    }

    private function bfs($s) {
        $this->level = array_fill(0, $this->n, -1);
        $queue = new SplQueue();
        $this->level[$s] = 0;
        $queue->enqueue($s);
        while (!$queue->isEmpty()) {
            $v = $queue->dequeue();
            foreach ($this->graph[$v] as $edge) {
                if ($edge->capacity > 0 && $this->level[$edge->to] < 0) {
                    $this->level[$edge->to] = $this->level[$v] + 1;
                    $queue->enqueue($edge->to);
                }
            }
        }
        return $this->level;
    }

    private function dfs($v, $t, $f) {
        if ($v == $t) return $f;
        for ($i = $this->iter[$v]; $i < count($this->graph[$v]); $i++) {
            $edge = $this->graph[$v][$i];
            if ($edge->capacity > 0 && $this->level[$v] < $this->level[$edge->to]) {
                $d = $this->dfs($edge->to, $t, min($f, $edge->capacity));
                if ($d > 0) {
                    $edge->capacity -= $d;
                    $this->graph[$edge->to][$edge->rev]->capacity += $d;
                    return $d;
                }
            }
        }
        return 0;
    }

    public function maxFlow($s, $t) {
        $flow = 0;
        while (true) {
            $this->bfs($s);
            if ($this->level[$t] < 0) return $flow;
            $this->iter = array_fill(0, $this->n, 0);
            $f = $this->dfs($s, $t, PHP_INT_MAX);
            while ($f > 0) {
                $flow += $f;
                $f = $this->dfs($s, $t, PHP_INT_MAX);
            }
        }
    }

    public function getGraph() {
        return $this->graph;
    }
}

