        }
        for ($i = 0; $i < $this->m; $i++) {
            $line = fgets($handle);
            list($a, $b) = array_map('intval', explode(' ', trim($line)));
            $a--;
            $b--;
            $this->adj[$a][] = $b;
            $this->revAdj[$b][] = $a;
        }
        fclose($handle);
    }

    private function process() {
        $this->visited = array_fill(0, $this->n, false);
        $this->onPath = array_fill(0, $this->n, false);
        $this->result = array_fill(0, $this->n, 0);

        for ($i = 0; $i < $this->n; $i++) {
            if ($this->f[$i] == 1) {
                $this->dfs($i);
            }
        }
    }

    private function dfs($v) {
        $this->visited[$v] = true;
        $this->onPath[$v] = true;

        foreach ($this->adj[$v] as $to) {
            if ($this->f[$to] == 1) {
                continue;
            }
            if (!$this->visited[$to]) {
                $this->dfs($to);
            }
        }

        if ($this->f[$v] == 2) {
            $this->markPath($v);
        }

        $this->onPath[$v] = false;
    }

    private function markPath($v) {
        $this->result[$v] = 1;
        foreach ($this->revAdj[$v] as $from) {
            if ($this->onPath[$from] && $this->f[$from] != 1) {
                $this->markPath($from);
            }
        }
    }

    private function output() {
        $handle = fopen("php://stdout", "w");
        for ($i = 0; $i < $this->n; $i++) {
            fwrite($handle, $this->result[$i] . "\n");
        }
        fclose($handle);
    }
}

