        // to a "use" state, with no other "assign" state in between.
        // We do this by traversing the forward graph starting from "assign" states,
        // but only through visited states, and stopping if we hit another "assign" state.
        $queue = new SplQueue();
        for ($i = 0; $i < $this->n; $i++) {
